# dedupe_sorted :: [1, 1, 2, 2, 3]
def dedupe_sorted(xs):
    if not xs:
        return xs
    out = [xs[0]]
    for x in xs[1:]:
        if x != out[-1]:
            out.append(x)
    return out

if __name__ == '__main__':
    print(dedupe_sorted([1, 1, 2, 2, 3]))

